class LaunchCheck(_Resource):
    """Launch Check: pre-send checks of links, one at a time or in bulk runs."""

    def get(self, link_id: int, *, request_options: Optional[Dict[str, Any]] = None) -> Any:
        """Latest Result

        The latest stored result for the link, with `stale`, `destination_changed` and its sign-off. `data` is null when the link was never checked.

        ``GET /launch-check/links/{link_id}``; permission: read
        """
        return self._client._request('GET', '/launch-check/links/{link_id}', path_params={'link_id': link_id}, options=request_options)

    def run(self, link_id: int, *, request_options: Optional[Dict[str, Any]] = None) -> Any:
        """Check One Link Now

        Runs every pre-send check (destination, redirects, HTTPS, mobile, smart rules, UTM tags, link previews, QR print quality, security) and stores the result. Counts toward 120 checks per hour per account.

        ``POST /launch-check/links/{link_id}``; permission: write
        """
        return self._client._request('POST', '/launch-check/links/{link_id}', path_params={'link_id': link_id}, options=request_options)

    def start_run(self, body: Optional[Dict[str, Any]] = None, /, *, request_options: Optional[Dict[str, Any]] = None, **fields: Any) -> Any:
        """Start a Bulk Run

        Checks up to 200 links on our servers. Subscribe a webhook to `launch_check.run_completed` instead of polling. One run per account at a time.

        ``POST /launch-check/runs``; permission: write
        """
        return self._client._request('POST', '/launch-check/runs', body=_body(body, fields), options=request_options)

    def get_run(self, run_id: int, *, after: Optional[int] = None, request_options: Optional[Dict[str, Any]] = None) -> Any:
        """Run Progress

        ``GET /launch-check/runs/{run_id}``; permission: read

        Query parameters:
            after: Full check details only for results with a larger id
        """
        return self._client._request('GET', '/launch-check/runs/{run_id}', path_params={'run_id': run_id}, query={'after': after}, options=request_options)

    def stop_run(self, run_id: int, *, request_options: Optional[Dict[str, Any]] = None) -> Any:
        """Stop a Run

        ``POST /launch-check/runs/{run_id}/stop``; permission: write
        """
        return self._client._request('POST', '/launch-check/runs/{run_id}/stop', path_params={'run_id': run_id}, options=request_options)

    def check_sms_message(self, body: Optional[Dict[str, Any]] = None, /, *, request_options: Optional[Dict[str, Any]] = None, **fields: Any) -> Any:
        """Check an SMS Message

        Checks an SMS text before you send it, the way a carrier and a phone will see it: GSM-7 or Unicode (UCS-2) encoding and the characters that forced Unicode (with plain replacements where they exist), characters and SMS parts (160/153 GSM, 70/67 Unicode), the links in the text (your short links with their latest Launch Check verdict, public shorteners that phone spam filters often flag, several links, http://) and opt-out wording. With a `country` or one of your `sender_id`s it adds that route's rules, as confirmed by BroadNet: promotional sender IDs need AD- (UAE) or -AD (Saudi Arabia), promotional messages have quiet hours (21:00-07:00 UAE, 22:00-09:00 Saudi Arabia, 01:00-12:00 during Ramadan) and need opt-out wording. A sender ID's own domain and link mode are checked for consistency (information only: carriers control the sender ID, not the links). Sends nothing and stores nothing (permission read).

        ``POST /launch-check/sms-message``; permission: read
        """
        return self._client._request('POST', '/launch-check/sms-message', body=_body(body, fields), options=request_options)

